 10	abstract class BaseParamsHandlerContainer implements ParamsHandlerContainerInterface
 11	{
 12	    /**
 13	     * @var APIHandlerInterface[]
 14	     */
 15	    private array $handlers = array();
 16	    private APIMethodInterface $method;
 17	
 18	    public function __construct(APIMethodInterface $method)
 19	    {
 20	        $this->method = $method;
 21	    }
 22	
 23	    public function getMethod(): APIMethodInterface
 24	    {
 25	        return $this->method;
 26	    }
 27	
 28	    public function getManager() : APIParamManager
 29	    {
 30	        return $this->method->manageParams();
 31	    }
 32	
 33	    protected function registerHandler(APIHandlerInterface $handler) : void
 34	    {
 35	        $this->handlers[] = $handler;
 36	    }
 37	
 38	    public function resolveValue() : mixed
 39	    {
 40	        foreach($this->handlers as $handler) {
 41	            $value = $handler->resolveValue();
 42	            if($value !== null) {
 43	                return $value;
 44	            }
 45	        }
 46	
 47	        return null;
 48	    }
 49	
 50	    public function getAll() : array
 51	    {
 52	        return $this->handlers;
 53	    }
 54	
 55	    /**
 56	     * @return class-string<APIHandlerInterface>[]
 57	     */
 58	    public function getIDs() : array
 59	    {
 60	        $results = array();
 61	
 62	        foreach($this->handlers as $handler) {
 63	            $results[] = get_class($handler);
 64	        }
 65	
 66	        return $results;
 67	    }
 68	
 69	    /**
 70	     * @return string[]
 71	     */
 72	    public function getParamNames() : array
 73	    {
 74	        $results = array();
 75	        foreach($this->getAll() as $handler) {
 76	            foreach($handler->getParams() as $param) {
 77	                $results[] = $param->getName();
 78	            }
 79	        }
 80	
 81	        $results = array_unique($results);
 82	
 83	        sort($results);
 84	
 85	        return $results;
 86	    }
