 88	    abstract protected function isValidValueType(string|int|float|bool|array|object $value) : bool;
 89	
 90	    public function requireValue() : string|int|float|bool|array|object
 91	    {
 92	        $value = $this->resolveValue();
 93	
 94	        if($value !== null && $this->isValidValueType($value)) {
 95	            return $value;
 96	        }
 97	
 98	        $this->method->errorResponse(APIMethodInterface::ERROR_NO_VALUE_AVAILABLE)
 99	            ->setErrorMessage(
100	                'Value not specified, parameters could not be resolved to a known record. '.PHP_EOL.

101	                'The method has used the following parameters to resolve a value: '.PHP_EOL.
102	                '- %s',
103	                implode(PHP_EOL.'- ', $this->getParamNames())
104	            )
105	            ->send();
106	    }
107	
108	    /**
109	     * Selects the given value in all handlers that support value selection.
110	     *
111	     * > NOTE: This should be the final value type returned by the parameter or rule.
112	     *  > For example: If the parameter is an integer ID, this should select
113	     *  > the record object.
114	     *
115	     * @param string|int|float|bool|array<int|string,mixed>|object $value
116	     * @return $this
117	     */
118	    public function selectValue(string|int|float|bool|array|object $value): self
