175	### Step 4: Create `StringListParameter.php`
176	
177	**Path:** `src/classes/Application/API/Parameters/Type/StringListParameter.php`
178	
179	New reusable framework parameter type for `string[]` values. Mirrors `IDListParameter` but preserves string values instead of casting to `int`. Accepts comma-separated strings or arrays, trims whitespace, and filters out empty strings.
180	
181	```php
182	namespace Application\API\Parameters\Type;
183	
184	class StringListParameter extends BaseAPIParameter
185	{
186	    public function getTypeLabel(): string
187	    {
188	        return t('String List');
189	    }
190	
191	    /**
192	     * @return string[]
193	     */
194	    public function getDefaultValue(): array
195	    {
196	        return $this->defaultValue ?? array();
197	    }
198	
199	    /**

200	     * @param array<int|string,string>|string|NULL $default An array of strings or a comma-separated string. Set to `NULL` to reset to an empty array. Other value types are ignored.
201	     * @return $this
202	     */
203	    public function setDefaultValue(int|float|bool|string|array|null $default) : self
204	    {
205	        return parent::setDefaultValue($this->filterValues($this->requireValidType($default)));
206	    }
207	
208	    /**
209	     * @param array<int|string,string>|string|null $value
210	     * @return BaseAPIParameter
211	     * @throws APIParameterException
212	     */
213	    public function selectValue(float|int|bool|array|string|null $value): BaseAPIParameter
214	    {
215	        return parent::selectValue($this->filterValues($this->requireValidType($value)));
216	    }
217	
218	    /**
219	     * @param array<int|string,mixed> $values
220	     * @return string[]
221	     */
222	    private function filterValues(array $values) : array
223	    {
224	        $result = array();
225	
226	        foreach($values as $item)
227	        {
228	            $item = trim(toString($item));
229	            if($item !== '') {
230	                $result[] = $item;
231	            }
232	        }
233	
234	        return $result;
235	    }
236	
237	    /**
238	     * @param mixed $value
239	     * @return array<int|string,mixed>
240	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
241	     */
242	    private function requireValidType(mixed $value) : array
243	    {
244	        if($value === null) {
245	            return array();
246	        }
247	
248	        if(is_array($value)) {
249	            return $value;
250	        }
251	
252	        if(is_string($value)) {
253	            return ConvertHelper::explodeTrim(',', $value);
254	        }
255	
256	        throw new APIParameterException(
257	            'Invalid parameter value.',
258	            sprintf(
259	                'Expected an array or comma-separated string, given: [%s].',
260	                gettype($value)
261	            ),
262	            APIParameterException::ERROR_INVALID_PARAM_VALUE
263	        );
264	    }
265	
266	    /**
267	     * @return string[]|null
268	     */
269	    protected function resolveValue(): array|null
270	    {
271	        $value = $this->getRequestParam()->get();
272	
273	        if($value === null) {
274	            return null;
275	        }
276	
277	        if(!is_array($value) && !is_string($value)) {
278	            $this->result->makeWarning(
279	                'Ignoring non-array, non-string value.',
280	                ParamValidationInterface::VALIDATION_INVALID_VALUE_TYPE
281	            );
282	            return null;
283	        }
284	
285	        if(is_string($value)) {
286	            $value = ConvertHelper::explodeTrim(',', $value);
287	        }
288	
289	        $result = array();
290	        foreach($value as $item) {
291	            $item = trim(toString($item));
292	            if($item !== '') {
293	                $result[] = $item;
294	            }
295	        }
296	
297	        return $result;
298	    }

